import random

import pytest

from debruijn import DeBruijnGraph, generate_sequence, make_reads

K = 21
READ_LEN = 50


@pytest.fixture(scope="module")
def data():
    # generate_sequence bumps the seed internally if the draw contains a
    # repeated 20-mer; it returns (sequence, seed_actually_used).
    seq, seed_used = generate_sequence(length=500, seed=11, k=K)
    return {"seq": seq, "seed": seed_used,
            "reads": make_reads(seq, read_len=READ_LEN)}

def test_assembled_contig_equals_original(data):
    g = DeBruijnGraph(data["reads"], k=K)
    assert g.assemble() == data["seq"]

